class TypeSpecificProjection(nn.Module):
    def __init__(self, input_dims, d):
        super(TypeSpecificProjection, self).__init__()
        self.projections = nn.ModuleDict({
            node_type: nn.Linear(input_dim, d) for node_type, input_dim in input_dims.items()
        })

    def forward(self, node_type, x):
        return self.projections[node_type](x)

