# --- Heterogeneous neighbor sampling and RWR-based strategies ---
import networkx as nx

def rwr_sampling(graph, node_type, restart_prob=0.15):
    G = graph[node_type]
    n = G.number_of_nodes()
    p = (1 - restart_prob) / G.degree(node_type)

    # Initialize the probability distribution
    prob_dist = {node: 1/n for node in G.nodes}

    for _ in range(10):  # Number of steps in RWR
        new_prob_dist = {}
        for node in G.nodes:
            new_prob_dist[node] = restart_prob / n + p * sum(prob_dist[neighbor] for neighbor in G.neighbors(node))
        prob_dist = new_prob_dist

    return prob_dist

def hetero_neighbor_sampling(graph, input_dims, d):
    projected_features = {}
    projection_layer = TypeSpecificProjection(input_dims, d)

    for node_type, x in graph.items():
        n = x.size(0)
        sampled_neighbors = {i: rwr_sampling(graph, node_type)[i] for i in range(n)}

        # Sort nodes based on their RWR scores
        sorted_indices = sorted(sampled_neighbors, key=sampled_neighbors.get, reverse=True)
        sorted_x = x[sorted_indices]

        projected_x = projection_layer(node_type, sorted_x)
        projected_features[node_type] = projected_x

    return projected_features

# Example usage:
